<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute} from 'vue-router'
import {ArrowLeft,ArrowUpRight,BriefcaseBusiness,Check,ChevronLeft,ChevronRight,GraduationCap,MapPin,Pencil,Phone,Plus,RefreshCw,ShieldCheck,UserRound,X} from '@lucide/vue'
import {api,accessToken} from '../lib/api.js'
import {auth} from '../lib/auth.js'
import {accountStatus,formatDateTime,personTypeLabel,resourceStatus,resourceStatusTone} from '../lib/format.js'
import {academicFields,contactFields,dossierTabs,educationFields,employmentFields,followupMethods,profileDraft,profileUpdate,displayDate,recordDraft,recordUpdate,internalRecordLabels,internalStatuses} from '../lib/dossier.js'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import PanelState from '../components/PanelState.vue'
import RegionSelect from '../components/RegionSelect.vue'
import StatusBadge from '../components/StatusBadge.vue'

const route=useRoute(), dossier=ref(null), loading=ref(true), error=ref(''),notice=ref(''),tab=ref('basic'),sectionLoading=ref(false)
const editKind=ref(''),draft=ref(profileDraft()),editError=ref(''),busy=ref(false),tagInput=ref(''),followup=ref(null),revealOpen=ref(false),revealReason=ref(''),studentId=ref(''),discardOpen=ref(false)
const recordForm=ref(null),recordOriginal=ref(''),archiveTarget=ref(null),archiveReason=ref(''),peopleQuery=ref(''),people=ref([]),peopleLoading=ref(false),selectedPerson=ref(''),tagGroup=ref('综合标签')
let generation=0,controller=null,revealTimer=null,discardResolve=null,peopleGeneration=0
const account=computed(()=>dossier.value?.account||{}), supplement=computed(()=>dossier.value?.supplement||{}), profile=computed(()=>supplement.value.profile||profileDraft())
const selectedTab=computed(()=>dossierTabs.find(item=>item.key===tab.value)||dossierTabs[0])
const section=computed(()=>dossier.value?.tabs?.[tab.value]||{items:[],total:0,page:1,pageSize:50})
const countKeys=['resources','enterprises','activities','giving','followups','relations']
const currentEmployment=computed(()=>profile.value.employment.find(row=>!row.endDate)||profile.value.employment[0])
const dirty=computed(()=>(!!editKind.value&&JSON.stringify(profileUpdate(editKind.value,draft.value))!==JSON.stringify(profileUpdate(editKind.value,profileDraft(profile.value))))||!!tagInput.value.trim()||!!followup.value&&!![followup.value.content,followup.value.title,followup.value.keyPoints,followup.value.nextPlan].some(value=>value?.trim())||!!recordForm.value&&JSON.stringify(recordForm.value.fields)!==recordOriginal.value)
const editTitles={contacts:'维护联系方式',education:'维护教育经历',employment:'维护工作经历',tags:'维护校友标签',notes:'维护校内备注'}
const editTitle=computed(()=>editTitles[editKind.value]||'维护人员档案')
const metrics=computed(()=>dossier.value?.tabs?.analysis?.metrics||{})
const recordCategories={resources:['需求','供给'],enterprises:['合作项目','实习就业','科研合作','社会服务','其他'],activities:['校友活动','学校活动','座谈走访','其他'],giving:['捐赠意向','捐赠联系','项目沟通','其他'],relations:['校友关系','组织关系','合作关系','其他']}
function current(version,token,id){return version===generation&&token===accessToken()&&id===String(route.params.id)&&auth.isSuperAdmin.value}
function clearEditors(){editKind.value='';draft.value=profileDraft();followup.value=null;recordForm.value=null;archiveTarget.value=null;archiveReason.value='';people.value=[];peopleQuery.value='';peopleLoading.value=false;peopleGeneration++;selectedPerson.value='';revealOpen.value=false;revealReason.value='';editError.value='';tagInput.value='';tagGroup.value='综合标签';studentId.value='';clearTimeout(revealTimer)}
function clearPrivate(){generation++;controller?.abort();dossier.value=null;clearEditors();loading.value=false;busy.value=false;if(discardResolve){discardResolve(false);discardResolve=null;discardOpen.value=false}}
async function load(){
  const version=++generation,token=accessToken(),id=String(route.params.id);controller?.abort();controller=new AbortController();loading.value=true;sectionLoading.value=false;error.value='';dossier.value=null;clearEditors()
  try{const result=await api(`/admin/accounts/${encodeURIComponent(id)}/dossier`,{token,signal:controller.signal});if(current(version,token,id))dossier.value=result}
  catch(cause){if(current(version,token,id)&&cause.name!=='AbortError')error.value=cause.message}
  finally{if(current(version,token,id))loading.value=false}
}
async function loadSection(page){if(sectionLoading.value)return;const version=generation,token=accessToken(),id=String(route.params.id),key=tab.value;sectionLoading.value=true;error.value='';try{const result=await api(`/admin/accounts/${encodeURIComponent(id)}/dossier/${key}?${new URLSearchParams({page:String(page),pageSize:'50'})}`,{token});if(current(version,token,id)&&tab.value===key)dossier.value.tabs[key]=result}catch(cause){if(current(version,token,id))error.value=cause.message}finally{if(current(version,token,id))sectionLoading.value=false}}
function openEdit(kind){clearEditors();draft.value=profileDraft(profile.value);editKind.value=kind}
function addExperience(kind){if(draft.value[kind].length>=30)return;draft.value[kind].push(Object.fromEntries(Object.keys(kind==='education'?educationFields:employmentFields).map(key=>[key,''])))}
function addTag(){const value=(tagGroup.value==='综合标签'?'':`${tagGroup.value}：`)+tagInput.value.trim();if(!tagInput.value.trim()||value.length>30||draft.value.tags.length>=30){if(value.length>30)editError.value='标签含分类前缀最多30字';return}if(!draft.value.tags.includes(value))draft.value.tags.push(value);tagInput.value='';editError.value=''}
async function mutate(path,options,success){
  if(busy.value||!dossier.value||!auth.isSuperAdmin.value)return
  const version=generation,token=accessToken(),id=String(route.params.id);busy.value=true;editError.value='';error.value='';notice.value=''
  try{const result=await api(`/admin/accounts/${encodeURIComponent(id)}/dossier${path}`,{...options,token});if(!current(version,token,id))return;clearEditors();await load();if(token===accessToken()&&id===String(route.params.id)&&dossier.value)notice.value=success;return result}
  catch(cause){if(current(version,token,id)){if([401,403].includes(cause.status)){clearPrivate();error.value=cause.message}else{editError.value=cause.message;error.value=cause.code==='DOSSIER_REVISION_CONFLICT'?'档案已被其他管理员更新，请关闭编辑后刷新页面，再核对保存。':(!editKind.value&&!followup.value&&!recordForm.value&&!archiveTarget.value?cause.message:'')}}}
  finally{if(token===accessToken()&&id===String(route.params.id))busy.value=false}
}
function saveProfile(){if(editKind.value==='tags'){addTag();if(tagInput.value.trim())return}return mutate('/profile',{method:'PUT',body:{revision:supplement.value.revision,profile:profileUpdate(editKind.value,draft.value)}},'校内档案已保存，未修改学校核验资料或用户本人资料。')}
function today(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}
function openFollowup(){clearEditors();followup.value={method:'phone',title:'',content:'',keyPoints:'',nextPlan:'',occurredAt:today(),nextFollowUpAt:'',status:'pending'}}
function saveFollowup(){if(!followup.value?.content.trim()){editError.value='请填写沟通内容或跟进事项';return}return mutate('/followups',{method:'POST',body:{revision:supplement.value.revision,...followup.value}},'跟进记录已保存。')}
function setFollowupStatus(row){return mutate(`/followups/${encodeURIComponent(row.id)}`,{method:'PATCH',body:{revision:supplement.value.revision,status:row.status==='completed'?'pending':'completed'}},'跟进状态已更新。')}
function openRecord(row=null){clearEditors();recordForm.value={section:tab.value,id:row?.id||'',fields:recordDraft(tab.value,row||{})};recordOriginal.value=JSON.stringify(recordForm.value.fields);selectedPerson.value=row?.targetName||''}
function saveRecord(){const form=recordForm.value;if(!form?.fields.title.trim()){editError.value='请填写记录名称';return}if(form.section==='relations'&&!form.fields.relationship.trim()){editError.value='请填写实际关系类型';return}return mutate(`/records/${form.section}${form.id?`/${encodeURIComponent(form.id)}`:''}`,{method:form.id?'PUT':'POST',body:{revision:supplement.value.revision,...recordUpdate(form.section,form.fields)}},'内部记录已保存，未修改前台发布内容或业务审批状态。')}
function requestArchive(row){clearEditors();archiveTarget.value={...row,section:tab.value}}
function archiveRecord(){const row=archiveTarget.value;if(!row?.internal)return;return mutate(`/records/${row.section}/${encodeURIComponent(row.id)}`,{method:'DELETE',body:{revision:supplement.value.revision,reason:archiveReason.value}},'内部记录已归档，原始业务记录不受影响。')}
async function searchPeople(){const query=peopleQuery.value.trim();if(!query)return;const version=generation,token=accessToken(),id=String(route.params.id),search=++peopleGeneration;peopleLoading.value=true;editError.value='';try{const result=await api(`/admin/accounts?${new URLSearchParams({query,page:'1',pageSize:'30'})}`,{token});if(current(version,token,id)&&search===peopleGeneration&&recordForm.value?.section==='relations')people.value=result.items.filter(row=>row.id!==id)}catch(cause){if(current(version,token,id)&&search===peopleGeneration)editError.value=cause.message}finally{if(current(version,token,id)&&search===peopleGeneration)peopleLoading.value=false}}
function choosePerson(row){recordForm.value.fields.targetAccountId=row.id;selectedPerson.value=row.name||row.username;people.value=[];peopleQuery.value=''}
async function revealNumber(){
  if(busy.value||revealReason.value.trim().length<5)return
  const version=generation,token=accessToken(),id=String(route.params.id);busy.value=true;editError.value=''
  try{const result=await api(`/admin/accounts/${encodeURIComponent(id)}/dossier/student-number`,{method:'POST',token,body:{reason:revealReason.value.trim()}});if(current(version,token,id)){studentId.value=result.studentId;revealOpen.value=false;revealReason.value='';clearTimeout(revealTimer);revealTimer=setTimeout(()=>{studentId.value=''},60000)}}catch(cause){if(current(version,token,id))editError.value=cause.message}finally{if(current(version,token,id))busy.value=false}
}
function requestLeave(){if(busy.value){error.value='正在保存，请稍候再离开';return false}if(!dirty.value)return true;discardOpen.value=true;return new Promise(resolve=>{discardResolve=resolve})}
function discard(allowed){discardOpen.value=false;if(allowed)clearEditors();discardResolve?.(allowed);discardResolve=null}
function closeEditor(){if(busy.value)return;if(dirty.value){discardOpen.value=true;discardResolve=allowed=>{if(allowed)clearEditors()}}else clearEditors()}
function beforeUnload(event){if(dirty.value||busy.value){event.preventDefault();event.returnValue=''}}
function onStorage(event){if(event.key===null||event.key==='hufe.admin.access-token'){clearPrivate();error.value='登录账号已变化，请返回账号管理重新打开档案。'}}
watch(()=>route.params.id,()=>{tab.value='basic';notice.value='';load()},{immediate:true})
watch(()=>auth.state.user?.id,(next,previous)=>{if(next!==previous)clearPrivate()})
window.addEventListener('hufe:auth-expired',clearPrivate);window.addEventListener('beforeunload',beforeUnload);window.addEventListener('storage',onStorage)
onBeforeRouteLeave(requestLeave);onBeforeRouteUpdate(requestLeave)
onBeforeUnmount(()=>{clearPrivate();window.removeEventListener('hufe:auth-expired',clearPrivate);window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('storage',onStorage)})
</script>

<template>
  <div class="dossier-page">
    <nav class="dossier-breadcrumb" aria-label="面包屑"><RouterLink :to="{name:'accounts'}"><ArrowLeft :size="16"/>账号管理</RouterLink><span>/</span><span>{{ account.name||'人员档案' }}</span></nav>
    <PanelState :loading="loading" :error="!dossier?error:''" @retry="load"/>
    <template v-if="dossier&&!loading">
      <header class="dossier-hero panel">
        <div class="dossier-avatar" aria-hidden="true">{{ (account.name||account.username||'湖').slice(0,1) }}</div>
        <div class="dossier-hero-main"><div class="dossier-name"><h1>{{ account.name||account.username }}</h1><StatusBadge :tone="account.schoolIdentityVerified?'success':'warning'"><ShieldCheck :size="13"/>{{ account.schoolIdentityVerified?'已实名':'待实名校验' }}</StatusBadge><span class="dossier-kind">{{ personTypeLabel(account.personType) }}</span></div><p class="dossier-academic"><GraduationCap :size="17"/><span>{{ account.department||'学院 / 部门未提供' }}<template v-if="account.major"> · {{ account.major }}</template><template v-if="account.enrollmentYear"> · {{ account.enrollmentYear }}级</template></span></p><p class="dossier-work" v-if="currentEmployment"><BriefcaseBusiness :size="16"/><span>{{ currentEmployment.company }}<template v-if="currentEmployment.title"> · {{ currentEmployment.title }}</template></span></p><div class="dossier-hero-tags"><span v-for="label in profile.tags.slice(0,5)" :key="label">{{ label }}</span><span v-if="profile.tags.length>5">+{{ profile.tags.length-5 }}</span><span v-if="!profile.tags.length" class="dossier-muted">尚未添加校内标签</span></div></div>
        <div class="dossier-hero-actions"><span class="dossier-internal">校内工作档案</span><button class="button button-ghost" type="button" :disabled="busy" @click="load"><RefreshCw :size="15"/>刷新档案</button><small>更新于 {{ formatDateTime(supplement.updatedAt||account.updatedAt) }}</small></div>
      </header>
      <p class="dossier-privacy"><ShieldCheck :size="15"/>此页用于学校内部校友联系与维护；补充资料及跟进记录不展示在前台个人主页。</p>
      <div v-if="notice" class="dossier-message dossier-message--success" role="status"><Check :size="16"/>{{ notice }}<button type="button" aria-label="关闭提示" @click="notice=''"><X :size="15"/></button></div>
      <div v-if="error" class="dossier-message" role="alert">{{ error }}<button class="button button-ghost" type="button" :disabled="busy" @click="load">重新读取</button></div>
      <nav class="dossier-tabs" role="tablist" aria-label="人员档案板块"><button v-for="item in dossierTabs" :id="`dossier-tab-${item.key}`" :key="item.key" type="button" role="tab" :aria-selected="tab===item.key" :aria-controls="`dossier-panel-${item.key}`" :class="{selected:tab===item.key}" @click="tab=item.key">{{ item.label }}<small v-if="countKeys.includes(item.key)&&dossier.tabs[item.key]?.total">{{ dossier.tabs[item.key].total }}</small></button></nav>
      <section :id="`dossier-panel-${tab}`" class="dossier-content" role="tabpanel" :aria-labelledby="`dossier-tab-${tab}`">
        <template v-if="tab==='basic'">
          <section class="panel dossier-card"><header><div><h2>学校身份与学籍</h2><p>来自实名核验资料，此处只读</p></div><StatusBadge :tone="account.status==='active'?'success':'neutral'">{{ accountStatus(account.status) }}</StatusBadge></header><dl class="dossier-grid"><div v-for="field in academicFields(dossier)" :key="field.label"><dt>{{ field.label }}</dt><dd>{{ field.value||'未提供' }}</dd></div><div><dt>学工号</dt><dd class="dossier-student-number"><span>{{ studentId||account.studentIdMasked||'未提供' }}</span><button v-if="!studentId&&account.studentIdMasked" type="button" @click="revealOpen=true;editError=''">查看完整学工号</button><button v-if="studentId" type="button" @click="studentId=''">收起</button><small v-if="studentId">将在一分钟后自动收起</small></dd></div></dl></section>
          <section class="panel dossier-card"><header><div><h2>联系方式</h2><p>学校内部维护，与本人填写信息分开保存</p></div><button class="button button-ghost" type="button" @click="openEdit('contacts')"><Pencil :size="15"/>维护联系信息</button></header><dl class="dossier-grid"><div v-for="(label,key) in contactFields" v-show="key!=='regionCode'" :key="key"><dt>{{ label }}</dt><dd>{{ profile.contacts[key]||'未记录' }}</dd><small v-if="['phone','email','city'].includes(key)&&dossier.personalProfile?.fields?.[key]">本人填写：{{ dossier.personalProfile.fields[key] }}</small></div></dl></section>
          <div class="dossier-columns"><section v-for="kind in ['education','employment']" :key="kind" class="panel dossier-card"><header><div><h2>{{ kind==='education'?'教育经历':'工作经历' }}</h2><p>管理员补充 · {{ profile[kind].length }} 条</p></div><button class="button button-ghost" type="button" @click="openEdit(kind)"><Pencil :size="15"/>维护</button></header><div v-if="!profile[kind].length" class="dossier-empty">尚未补充{{ kind==='education'?'教育':'工作' }}经历</div><article v-for="(row,index) in profile[kind]" :key="index" class="dossier-experience"><span class="dossier-experience-icon"><component :is="kind==='education'?GraduationCap:BriefcaseBusiness" :size="19"/></span><div><h3>{{ row.school||row.company }}</h3><p>{{ [row.department,row.major,row.degree,row.title,row.industry].filter(Boolean).join(' · ')||'其他信息未填写' }}</p><small>{{ row.startYear||row.startDate||'起始时间未填写' }} — {{ row.endYear||row.endDate||(kind==='employment'?'至今':'结束时间未填写') }}</small><p v-if="row.note">{{ row.note }}</p></div></article></section></div>
          <section class="panel dossier-card"><header><div><h2>人物简介与校内备注</h2><p>可记录人物背景、核心成就、联系偏好及持续维护事项</p></div><button class="button button-ghost" type="button" @click="openEdit('notes')"><Pencil :size="15"/>编辑备注</button></header><template v-if="dossier.personalProfile?.fields?.bio"><h3 class="dossier-subtitle">本人填写的简介</h3><p class="dossier-longtext">{{ dossier.personalProfile.fields.bio }}</p></template><h3 class="dossier-subtitle">学校内部补充</h3><p class="dossier-longtext">{{ profile.notes||'暂无人物简介、核心成就或校内备注' }}</p></section>
        </template>
        <template v-else-if="tab==='tags'"><section class="panel dossier-card"><header><div><h2>校友标签</h2><p>学校资料自动标签与校内人工标签分开维护</p></div><button class="button button-primary" type="button" @click="openEdit('tags')"><Plus :size="16"/>维护标签</button></header><h3 class="dossier-subtitle">资料标签 <small>根据已有身份与学籍字段生成</small></h3><div class="dossier-tag-list"><span v-for="label in dossier.tabs.tags.automatic" :key="label" class="dossier-tag dossier-tag--automatic">{{ label }}</span></div><h3 class="dossier-subtitle">校内维护标签 <small>管理员补充</small></h3><div class="dossier-tag-list"><span v-for="label in profile.tags" :key="label" class="dossier-tag">{{ label }}</span><p v-if="!profile.tags.length" class="dossier-muted">暂无人工标签，可添加能力、资源与合作意向等标签。</p></div></section></template>
        <template v-else-if="tab==='analysis'"><section class="panel dossier-card"><header><div><h2>资料概览</h2><p>基于已关联记录汇总，不进行未接入模型的 AI 推测</p></div></header><div class="dossier-metrics"><div v-for="item in [{label:'合作供需',key:'resourceCount'},{label:'关联企业',key:'enterpriseCount'},{label:'活动 / 返校申请',key:'activityRegistrationCount'},{label:'已确认捐赠',key:'confirmedGivingCount'},{label:'跟进记录',key:'followupCount'},{label:'已加入组织',key:'organizationCount'}]" :key="item.key"><strong>{{ metrics[item.key]||0 }}</strong><span>{{ item.label }}</span></div></div><h3 class="dossier-subtitle">已有记录反映的事实</h3><p v-for="statement in dossier.tabs.analysis.statements" :key="statement" class="dossier-fact"><Check :size="16"/>{{ statement }}</p><p v-for="limitation in dossier.tabs.analysis.limitations" :key="limitation" class="dossier-muted">{{ limitation }}</p></section></template>
        <template v-else>
          <section class="panel dossier-card"><header><div><h2>{{ selectedTab.label }}</h2><p>{{ ({resources:'本人发布与校内维护的需求、资源供给分开标注',enterprises:'关联企业记录与学校内部合作项目分开维护',activities:'系统申请记录与校内活动备注分开保存，不等同于签到',giving:'区分参与意向、内部联系备注与学校确认的捐赠',followups:'学校内部沟通与后续联系安排',relations:'已核验学籍关系与管理员记录的关系分开标注'})[tab] }}</p></div><button v-if="tab==='followups'" class="button button-primary" type="button" @click="openFollowup"><Plus :size="16"/>新增跟进</button><button v-else class="button button-primary" type="button" @click="openRecord()"><Plus :size="16"/>新增{{ internalRecordLabels[tab] }}</button></header>
          <div v-if="!section.items.length" class="dossier-empty"><UserRound :size="28"/><strong>暂无{{ selectedTab.label }}</strong><span>有实际记录后将显示在这里，不按同名推测关联。</span></div>
          <div v-else class="dossier-records" :aria-busy="sectionLoading">
            <article v-for="row in section.items" :key="row.id" class="dossier-record"><div class="dossier-record-heading"><h3>{{ row.title||row.name||row.projectTitle||(tab==='followups'?followupMethods[row.method]+'跟进':'已关联记录') }}</h3><StatusBadge v-if="row.status" :tone="resourceStatusTone(row.status)">{{ row.internal?internalStatuses[row.status]:tab==='followups'?(row.status==='completed'?'已完成':'待跟进'):resourceStatus(row.status) }}</StatusBadge></div>
              <template v-if="row.internal"><p>{{ [row.category,row.partner,row.relationship].filter(Boolean).join(' · ') }} <span v-if="row.priority==='high'" class="dossier-priority">重点跟进</span></p><p v-if="row.description" class="dossier-longtext">{{ row.description }}</p><dl class="dossier-inline-data"><div v-if="row.occurredAt"><dt>发生 / 开始日期</dt><dd>{{ displayDate(row.occurredAt) }}</dd></div><div v-if="row.validUntil"><dt>有效截止 / 结束日期</dt><dd>{{ displayDate(row.validUntil) }}</dd></div><div v-if="row.cooperationModes?.length"><dt>合作方式</dt><dd>{{ row.cooperationModes.join('、') }}</dd></div></dl><div v-for="(label,key) in {resources:'投入 / 可供资源',progress:'推进情况',outcomes:'成果记录'}" :key="key"><template v-if="row[key]"><h4 class="dossier-record-subtitle">{{ label }}</h4><p class="dossier-longtext">{{ row[key] }}</p></template></div><p v-if="tab==='giving'&&row.amount!==null&&row.amount!==undefined">内部金额备注：¥ {{ Number(row.amount).toFixed(2) }}<br/><small>{{ row.amountNote }}</small></p><RouterLink v-if="row.targetAccountId" class="dossier-record-link" :to="{name:'accountDossier',params:{id:row.targetAccountId}}">{{ row.targetName||'关联人员' }}<ArrowUpRight :size="15"/></RouterLink><div class="dossier-record-actions"><button class="button button-ghost" type="button" :disabled="busy" @click="openRecord(row)"><Pencil :size="14"/>编辑记录</button><button class="button button-ghost" type="button" :disabled="busy" @click="requestArchive(row)">归档记录</button></div></template>
              <template v-if="!row.internal&&tab==='resources'"><p>{{ [row.category,row.organization,row.city].filter(Boolean).join(' · ') }}</p><p class="dossier-longtext">{{ row.summary||'暂未填写供需说明' }}</p><dl class="dossier-inline-data"><div v-if="row.cooperationMode"><dt>合作方式</dt><dd>{{ row.cooperationMode }}</dd></div><div v-if="row.targetAudience"><dt>面向群体</dt><dd>{{ row.targetAudience }}</dd></div></dl></template>
              <template v-if="!row.internal&&tab==='enterprises'"><p>{{ [row.industry,row.city,row.scale].filter(Boolean).join(' · ')||'企业补充信息未提供' }}</p><p>{{ row.relation }}</p><p v-if="row.summary" class="dossier-longtext">{{ row.summary }}</p></template>
              <template v-if="!row.internal&&tab==='activities'"><p v-if="row.startAt">活动 / 来访日期：{{ displayDate(row.startAt) }}</p><p v-if="row.location"><MapPin :size="14"/>{{ row.location }}</p></template>
              <template v-if="!row.internal&&tab==='giving'"><div class="dossier-giving-amount"><strong>{{ row.certificate?.certificateNo?`¥ ${Number(row.certificate.confirmedAmount||0).toFixed(2)}`:'尚未确认捐赠到账' }}</strong><span>{{ row.certificate?.certificateNo?'学校已确认金额':`登记意向金额：${row.intentAmount??'未填写'}` }}</span></div><p v-if="row.certificate?.certificateNo">证书编号：{{ row.certificate.certificateNo }}</p><p v-if="row.certificate?.issuedAt">签发日期：{{ displayDate(row.certificate.issuedAt) }}</p></template>
              <template v-if="tab==='followups'"><p class="dossier-longtext">{{ row.content }}</p><template v-if="row.keyPoints"><h4 class="dossier-record-subtitle">沟通要点</h4><p class="dossier-longtext">{{ row.keyPoints }}</p></template><template v-if="row.nextPlan"><h4 class="dossier-record-subtitle">后续计划</h4><p class="dossier-longtext">{{ row.nextPlan }}</p></template><dl class="dossier-inline-data"><div><dt>沟通日期</dt><dd>{{ displayDate(row.occurredAt) }}</dd></div><div><dt>记录人员</dt><dd>{{ row.creatorName }}</dd></div><div v-if="row.nextFollowUpAt"><dt>下次跟进</dt><dd>{{ displayDate(row.nextFollowUpAt) }}</dd></div></dl><button class="button button-ghost" type="button" :disabled="busy" @click="setFollowupStatus(row)">{{ row.status==='completed'?'改为待跟进':'标记已完成' }}</button></template>
              <template v-if="!row.internal&&tab==='relations'"><p>{{ row.relationship }}<template v-if="row.department"> · {{ row.department }}</template></p><RouterLink v-if="row.type==='account'" class="dossier-record-link" :to="{name:'accountDossier',params:{id:row.targetId}}">查看人员档案<ArrowUpRight :size="15"/></RouterLink></template>
              <footer><span>{{ row.source||'学校内部工作记录' }}</span><time v-if="row.createdAt">{{ formatDateTime(row.createdAt) }}</time></footer>
            </article>
          </div>
          <footer class="dossier-pagination" v-if="section.total"><span>共 {{ section.total }} 条记录</span><div><button class="button button-ghost" type="button" :disabled="sectionLoading||section.page<=1" aria-label="上一页记录" @click="loadSection(section.page-1)"><ChevronLeft :size="16"/></button><span>{{ section.page }} / {{ Math.max(1,Math.ceil(section.total/section.pageSize)) }}</span><button class="button button-ghost" type="button" :disabled="sectionLoading||section.page*section.pageSize>=section.total" aria-label="下一页记录" @click="loadSection(section.page+1)"><ChevronRight :size="16"/></button></div></footer>
          </section>
        </template>
      </section>
    </template>
    <ConfirmDialog :open="!!recordForm" :title="`${recordForm?.id?'编辑':'新增'}${internalRecordLabels[recordForm?.section]||'内部记录'}`" description="学校内部工作记录，不发布到前台，不修改报名、认证、到账或证书状态。" confirm-text="保存内部记录" tone="primary" wide :busy="busy" @cancel="closeEditor" @confirm="saveRecord">
      <div v-if="recordForm" class="dossier-editor"><p v-if="editError" class="dossier-form-error" role="alert">{{ editError }}</p><div class="dossier-form-grid">
        <label class="dossier-full"><span>记录名称 *</span><input v-model="recordForm.fields.title" maxlength="160" required/></label>
        <label><span>记录分类</span><select v-model="recordForm.fields.category"><option value="">请选择分类</option><option v-if="recordForm.fields.category&&!recordCategories[recordForm.section].includes(recordForm.fields.category)" :value="recordForm.fields.category">{{ recordForm.fields.category }}</option><option v-for="category in recordCategories[recordForm.section]" :key="category" :value="category">{{ category }}</option></select></label>
        <label><span>推进状态</span><select v-model="recordForm.fields.status"><option v-for="(label,key) in internalStatuses" :key="key" :value="key">{{ label }}</option></select></label>
        <label><span>跟进优先级</span><select v-model="recordForm.fields.priority"><option value="normal">常规</option><option value="high">重点跟进</option><option value="low">一般关注</option></select></label>
        <label v-if="'partner' in recordForm.fields"><span>合作单位 / 联系对象</span><input v-model="recordForm.fields.partner" maxlength="160"/></label>
        <label><span>发生 / 开始日期</span><input v-model="recordForm.fields.occurredAt" type="date"/></label><label><span>有效截止 / 结束日期</span><input v-model="recordForm.fields.validUntil" type="date"/></label>
        <label v-if="'cooperationModes' in recordForm.fields" class="dossier-full"><span>合作方式（每行一项，最多12项）</span><textarea :value="recordForm.fields.cooperationModes.join('\n')" rows="2" maxlength="611" @input="recordForm.fields.cooperationModes=$event.target.value.split('\n')"/></label>
        <label v-if="recordForm.section==='giving'"><span>内部金额备注（元，选填）</span><input v-model="recordForm.fields.amount" type="number" min="0" max="1000000000" step="0.01"/><small>仅作工作备注，不作为到账确认，不签发证书。</small></label>
        <template v-if="recordForm.section==='relations'"><label><span>实际关系类型 *</span><input v-model="recordForm.fields.relationship" maxlength="100" placeholder="例如：校友联络人、合作联系人" required/></label><div class="dossier-full dossier-person-select"><label><span>关联系统人员（选填）</span><div class="dossier-person-search"><input v-model="peopleQuery" type="search" placeholder="输入姓名或用户名查找" maxlength="80" aria-label="查找关联人员" @keydown.enter.prevent="searchPeople"/><button class="button button-ghost" type="button" :disabled="peopleLoading||!peopleQuery.trim()" @click="searchPeople">{{ peopleLoading?'查询中…':'查询' }}</button></div></label><p v-if="selectedPerson">已关联：{{ selectedPerson }}<button type="button" @click="recordForm.fields.targetAccountId='';selectedPerson=''">取消关联</button></p><div v-if="people.length" class="dossier-person-results"><button v-for="person in people" :key="person.id" type="button" @click="choosePerson(person)"><strong>{{ person.name||person.username }}</strong><small>{{ person.username }} · {{ person.department||'部门未提供' }}</small></button></div></div></template>
        <label class="dossier-full"><span>内容说明（最多3000字）</span><textarea v-model="recordForm.fields.description" maxlength="3000" rows="4"/></label>
        <template v-for="(label,key) in {resources:'投入 / 可供资源',progress:'推进情况',outcomes:'成果记录'}" :key="key"><label v-if="key in recordForm.fields" class="dossier-full"><span>{{ label }}</span><textarea v-model="recordForm.fields[key]" :maxlength="key==='progress'?1500:2000" rows="3"/></label></template>
      </div></div>
    </ConfirmDialog>
    <ConfirmDialog :open="!!archiveTarget" title="归档内部记录？" :description="`将归档“${archiveTarget?.title||''}”，保留历史与审计记录，不删除原有业务数据。`" confirm-text="确认归档" :busy="busy" @cancel="clearEditors" @confirm="archiveRecord"><div class="dossier-editor"><p v-if="editError" class="dossier-form-error" role="alert">{{ editError }}</p><label class="dossier-note-field"><span>归档说明（选填）</span><textarea v-model="archiveReason" rows="3" maxlength="300"/></label></div></ConfirmDialog>
    <ConfirmDialog :open="!!editKind" :title="editTitle" description="本次只维护该人员的校内补充档案，不修改学校实名核验资料。" confirm-text="保存档案" tone="primary" wide :busy="busy" @cancel="closeEditor" @confirm="saveProfile">
      <div class="dossier-editor"><p v-if="editError" class="dossier-form-error" role="alert">{{ editError }}</p>
        <div v-if="editKind==='contacts'" class="dossier-form-grid"><label v-for="key in ['phone','email','wechat']" :key="key"><span>{{ contactFields[key] }}</span><input v-model="draft.contacts[key]" :type="key==='email'?'email':'text'" :maxlength="key==='email'?160:key==='phone'?32:100" autocomplete="off"/></label><label><span>所在地区</span><RegionSelect v-model="draft.contacts.city" v-model:code="draft.contacts.regionCode" :disabled="busy"/></label><label class="dossier-full"><span>详细联系地址</span><textarea v-model="draft.contacts.address" maxlength="240" rows="2"/></label></div>
        <template v-else-if="['education','employment'].includes(editKind)"><div v-for="(row,index) in draft[editKind]" :key="index" class="dossier-editor-entry"><header><strong>第 {{ index+1 }} 条{{ editKind==='education'?'教育':'工作' }}经历</strong><button type="button" :disabled="busy" :aria-label="`移除第${index+1}条经历`" @click="draft[editKind].splice(index,1)"><X :size="16"/>移除</button></header><div class="dossier-form-grid"><label v-for="(label,key) in editKind==='education'?educationFields:employmentFields" :key="key" :class="{'dossier-full':key==='note'}"><span>{{ label }}<b v-if="['school','company'].includes(key)"> *</b></span><textarea v-if="key==='note'" v-model="row[key]" maxlength="500" rows="2"/><input v-else v-model="row[key]" :type="key.endsWith('Date')?'date':'text'" :maxlength="key.endsWith('Year')?4:160" :inputmode="key.endsWith('Year')?'numeric':undefined" :required="['school','company'].includes(key)"/></label></div></div><button class="button button-ghost" type="button" :disabled="busy||draft[editKind].length>=30" @click="addExperience(editKind)"><Plus :size="16"/>添加{{ editKind==='education'?'教育':'工作' }}经历</button><p v-if="!draft[editKind].length" class="dossier-muted">暂无记录，可添加真实经历；学校核验资料不受此处增删影响。</p></template>
        <template v-else-if="editKind==='tags'"><label class="dossier-note-field"><span>标签分类</span><select v-model="tagGroup"><option>综合标签</option><option>能力标签</option><option>资源标签</option><option>合作意向</option></select></label><label class="dossier-tag-input"><span>新增标签（含分类最多30字，最多30个）</span><div><input v-model="tagInput" maxlength="30" placeholder="例如：技术指导、实习资源、愿参与校友活动" @keydown.enter.prevent="addTag"/><button class="button button-ghost" type="button" :disabled="busy||!tagInput.trim()||draft.tags.length>=30" @click="addTag">添加</button></div></label><div class="dossier-tag-list"><span v-for="label in draft.tags" :key="label" class="dossier-tag">{{ label }}<button type="button" :aria-label="`移除标签${label}`" :disabled="busy" @click="draft.tags=draft.tags.filter(item=>item!==label)"><X :size="14"/></button></span></div></template>
        <label v-else-if="editKind==='notes'" class="dossier-note-field"><span>校内备注（最多3000字）</span><textarea v-model="draft.notes" maxlength="3000" rows="8" placeholder="请记录可核实的事实、联系偏好与维护事项"/></label>
      </div>
    </ConfirmDialog>
    <ConfirmDialog :open="!!followup" title="新增校内跟进记录" description="记录实际沟通情况，仅供学校内部工作使用。" confirm-text="保存跟进" tone="primary" :busy="busy" wide @cancel="closeEditor" @confirm="saveFollowup"><div v-if="followup" class="dossier-editor"><p v-if="editError" class="dossier-form-error" role="alert">{{ editError }}</p><div class="dossier-form-grid"><label class="dossier-full"><span>跟进标题（选填）</span><input v-model="followup.title" maxlength="160"/></label><label><span>联系渠道</span><select v-model="followup.method"><option v-for="(label,key) in followupMethods" :key="key" :value="key">{{ label }}</option></select></label><label><span>沟通日期</span><input v-model="followup.occurredAt" type="date"/></label><label><span>下次跟进日期（选填）</span><input v-model="followup.nextFollowUpAt" type="date"/></label><label><span>跟进状态</span><select v-model="followup.status"><option value="pending">待跟进</option><option value="completed">已完成</option></select></label><label class="dossier-full"><span>沟通内容 / 跟进事项 *</span><textarea v-model="followup.content" rows="4" maxlength="3000" required/></label><label class="dossier-full"><span>沟通要点（选填）</span><textarea v-model="followup.keyPoints" rows="3" maxlength="2000"/></label><label class="dossier-full"><span>后续计划（选填）</span><textarea v-model="followup.nextPlan" rows="3" maxlength="2000"/></label></div></div></ConfirmDialog>
    <ConfirmDialog :open="revealOpen" title="查看完整学工号" description="仅用于授权校内工作，查看原因将记入审计日志。" confirm-text="记录原因并查看" tone="primary" :busy="busy" :confirm-disabled="revealReason.trim().length<5" @cancel="clearEditors" @confirm="revealNumber"><div class="dossier-editor"><p v-if="editError" class="dossier-form-error" role="alert">{{ editError }}</p><label class="dossier-note-field"><span>查看原因（5至300字，不要填写学工号）</span><textarea v-model="revealReason" rows="3" minlength="5" maxlength="300"/></label></div></ConfirmDialog>
    <ConfirmDialog :open="discardOpen" title="放弃未保存的修改？" description="未保存的校内档案内容将被清除，已保存的数据不会改变。" confirm-text="放弃修改" @cancel="discard(false)" @confirm="discard(true)"/>
  </div>
</template>

